(97, 'Umurongo ucagaguye wera mu muhanda usobanura iki?\r\n', 'Birabujijwe kuwurenga', 'Birabujijwe kuhahagarara', 'Wegereye ahaguteza ibyago', 'Kunyuranaho ntibyemewe', 'A', 'centreline.png'),
