INSERT INTO `exam_attempts` (`id`, `student_name`, `phone_number`, `score`, `total_questions`, `student_answers`, `exam_questions_snapshot`, `created_at`) VALUES
(1, 'erneste', '+250789245524', 17, 20, '{\"question_1\":\"B\",\"question_3\":\"A\",\"question_5\":\"D\",\"question_10\":\"D\",\"question_14\":\"D\",\"question_16\":\"C\",\"question_19\":\"D\",\"question_24\":\"C\",\"question_41\":\"A\",\"question_48\":\"B\",\"question_54\":\"C\",\"question_58\":\"D\",\"question_60\":\"C\",\"question_61\":\"C\",\"question_68\":\"B\",\"question_71\":\"D\",\"question_79\":\"D\",\"question_81\":\"B\",\"question_85\":\"C\",\"question_91\":\"A\"}', '[{\"id\":1,\"correct_option\":\"B\",\"question\":\"Mu gihe utwaye ikinyabiziga uva kuri A ugana kuri B, Iki kimenyetso kiri mu muhanda kivuze iki ?\\r\\n\",\"option_a\":\"Umuyobozi w’ikinyabiziga ashobora kunyuranaho arenze umurongo wera udacagaguye\",\"option_b\":\"Umuyobozi w’ikinyabiziga abujijwe kunyuranaho arenze imirongo yera\",\"option_c\":\"Umuyobozi w’ikinyabiziga yemerewe kunyuranaho\",\"option_d\":\"Abayobozi b’ibinyamitende gusa bemerewe kunyuranaho barenze umurongo wera udacagaguye\",\"image_path\":\"sign5.png\"},{\"id\":2,\"correct_option\":\"A\",\"question\":\"Ikinyabiziga cyose cyangwa ibinyabiziga\\r\\nbigenda bigomba kugira:\",\"option_a\":\"Umuyobozi\",\"option_b\":\"Umuherekeza\",\"option_c\":\"A na B ni ibisubizo by’ukuri\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":3,\"correct_option\":\"C\",\"question\":\"Ijambo “akayira” bivuga inzira\\r\\nnyabagendwa ifunganye yagenewe gusa:\",\"option_a\":\"Abanyamaguru\",\"option_b\":\"Ibinyabiziga bigendera ku biziga bibiri\",\"option_c\":\"A na B ni ibisubizo by’ukuri\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":4,\"correct_option\":\"C\",\"question\":\"Umurongo uciyemo uduce umenyesha\\r\\nahegereye umurongo ushobora kuzuzwa\\r\\nn’uturanga gukata tw’ibara ryera utwo\\r\\nturanga cyerekezo tumenyesha :\",\"option_a\":\"Igisate cy’umuhanda abayobozi bagomba gukurikira\",\"option_b\":\"Ahegereye umurongo ukomeje\",\"option_c\":\"Igabanurwa ry’umubare w’ibisate by’umuhanda mu cyerekezo bajyamo\",\"option_d\":\"A na C nibyo\",\"image_path\":null},{\"id\":5,\"correct_option\":\"D\",\"question\":\"Ahantu ho kugendera mu muhanda\\r\\nherekanwa n’ibimenyetso bimurika\\r\\nibinyabiziga ntibishobora kuhagenda :\",\"option_a\":\"Biteganye\",\"option_b\":\"Ku murongo umwe\",\"option_c\":\"A na B nibyo\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":6,\"correct_option\":\"D\",\"question\":\"Ibinyabiziga bikurikira bigomba gukorerwa\\r\\nisuzumwa buri mwaka:\",\"option_a\":\"Ibinyabiziga bigenewe gutwara abagenzi muri rusange\",\"option_b\":\"Ibinyabiziga bigenewe gutwara ibintu birengeje toni 3.5\",\"option_c\":\"Ibinyabiziga bigenewe kwigisha gutwara\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":7,\"correct_option\":\"D\",\"question\":\"Ubugari bwa romoruki ikuruwe\\r\\nn’ikinyamitende itatu ntibugomba kurenza\\r\\nibipimo bikurikira:\",\"option_a\":\"cm75\",\"option_b\":\"cm125\",\"option_c\":\"cm265\",\"option_d\":\"Nta gisubizo cy’ukuri\",\"image_path\":null},{\"id\":8,\"correct_option\":\"D\",\"question\":\"Uburebure bw’ibinyabiziga bikurikira\\r\\nntibugomba kurenga metero 11 :\",\"option_a\":\"Ibifite umutambiko umwe uhuza imipira\",\"option_b\":\"Ibifite imitambiko ibiri ikurikiranye mu bugari bwayo\",\"option_c\":\"Makuzungu\",\"option_d\":\"Nta gisubizo cy’ukuri\",\"image_path\":null},{\"id\":9,\"correct_option\":\"D\",\"question\":\"Ikinyabiziga kibujijwe guhagarara akanya\\r\\nkanini aha hakurikira :\",\"option_a\":\"Ahatarengeje metero 1 imbere cyangwa inyuma y’ikinyabiziga gihagaze akanya gato cyangwa kanini \",\"option_b\":\"Ahantu hari ibimenyetso bibuza byabugenewe\",\"option_c\":\"Aho abanyamaguru banyura mu muhanda ngo bakikire inkomyi\",\"option_d\":\"Ibisubizo byose nibyo\",\"image_path\":null},{\"id\":10,\"correct_option\":\"D\",\"question\":\"Kunyuranaho bikorerwa:\",\"option_a\":\"Mu ruhande rw’iburyo gusa\",\"option_b\":\"Igihe cyose ni ibumoso\",\"option_c\":\"Iburyo iyo unyura ku nyamaswa\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":11,\"correct_option\":\"D\",\"question\":\"Icyapa cyerekana umuvuduko ntarengwa\\r\\nikinyabiziga kitagomba kurenza gishyirwa gusa\\r\\nku binyabiziga bifite uburemere ntarengwa\\r\\nbukurikira:\",\"option_a\":\"Burenga toni 1\",\"option_b\":\"Burenga toni 2\",\"option_c\":\"Burenga toni 24\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":12,\"correct_option\":\"A\",\"question\":\"Ahatari mu nsisiro umuvuduko ntarengwa\\r\\nmu isaha wa velomoteri ni: \",\"option_a\":\"Km50\",\"option_b\":\"Km40\",\"option_c\":\"Km30\",\"option_d\":\"Nta gisubizo cy’ukuri\",\"image_path\":null},{\"id\":13,\"correct_option\":\"D\",\"question\":\"Umuyobozi ugenda mu muhanda igihe\\r\\nubugari bwawo budatuma anyuranaho nta\\r\\nnkomyi ashobora kunyura mu kayira\\r\\nk’abanyamaguru ariko amaze kureba ibi\\r\\nbikurikira:\",\"option_a\":\"Umuvuduko w’abanyamaguru\",\"option_b\":\"Ubugari bw’umuhanda\",\"option_c\":\"Umubare w’abanyamaguru\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":14,\"correct_option\":\"B\",\"question\":\"Ku byerekeye kwerekana ibinyabiziga\\r\\nn’ukumurika kwabyo ndetse no kwerekana\\r\\nihindura ry’ibyerekezo byabyo. Birabujijwe\\r\\ngukora andi matara cyangwa utugarurarumuri\\r\\nuretse ibitegetswe ariko ntibireba amatara\\r\\nakurikira:\",\"option_a\":\"Amatara ndanga\",\"option_b\":\"Amatara ari imbere mu modoka\",\"option_c\":\"Amatara ndangaburambarare\",\"option_d\":\"Ibisubizo byose nibyo\",\"image_path\":null},{\"id\":15,\"correct_option\":\"D\",\"question\":\"Iyo nta mategeko awugabanya\\r\\nby’umwihariko umuvuduko ntarengwa\\r\\nw’amapikipiki mu isaha ni:\",\"option_a\":\"Km25\",\"option_b\":\"Km70\",\"option_c\":\"Km40\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":16,\"correct_option\":\"C\",\"question\":\"Uburyo bukoreshwa kugirango ikinyabiziga\\r\\nkigende gahoro igihe feri idakora neza babwita:\",\"option_a\":\"Feri y’urugendo\",\"option_b\":\"Feri yo guhagarara umwanya munini\",\"option_c\":\"Feri yo gutabara\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":17,\"correct_option\":\"C\",\"question\":\"Nibura ikinyabiziga gitegetswe kugira\\r\\nuduhanagurakirahure tungahe:\",\"option_a\":\"2\",\"option_b\":\"3\",\"option_c\":\"1\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":18,\"correct_option\":\"B\",\"question\":\"Amatara maremare y’ikinyabiziga agomba\\r\\nkuzimwa mu bihe bikurikira:\",\"option_a\":\"Iyo umuhanda umurikiye umuyobozi abasha kureba muri metero 20\",\"option_b\":\"Iyo ikinyabiziga kigiye kubisikana n’ibindi\",\"option_c\":\"Iyo ari mu nsisiro\",\"option_d\":\"Ibisubizo byose ni ukuri\",\"image_path\":null},{\"id\":19,\"correct_option\":\"D\",\"question\":\"Ikinyabiziga ntigishobora kugira amatara\\r\\narenga abiri y’ubwoko bumwe keretse\\r\\nkubyerekeye amatara akurikira:\",\"option_a\":\"Itara ndangamubyimba\",\"option_b\":\"Itara ryerekana icyerekezo\",\"option_c\":\"Itara ndangaburumbarare\",\"option_d\":\"Ibisubizo byose ni ukuri\",\"image_path\":null},{\"id\":20,\"correct_option\":\"D\",\"question\":\"Ubugari bwa romoruki ikuruwe n’igare\\r\\ncyangwa velomoteri ntiburenza ibipimo\\r\\nbikurikira:\",\"option_a\":\"cm25\",\"option_b\":\"cm125\",\"option_c\":\"cm45\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":21,\"correct_option\":\"A\",\"question\":\"Ibinyabiziga bikoreshwa nka tagisi,\\r\\nbitegerereza abantu mu nzira nyabagendwa,\\r\\nbishobora gushyirwaho itara ryerekana ko\\r\\nikinyabiziga kitakodeshejwe. Iryo tara\\r\\nrishyirwaho ku buryo bukurikira:\",\"option_a\":\"Ni itara ry’icyatsi rishyirwa imbere ku kinyabiziga\",\"option_b\":\"Ni itara ry’icyatsi rishyirwa ibumoso\",\"option_c\":\"Ni itara ry’umuhondo rishyirwa inyuma\",\"option_d\":\"A na C ni ibisubizo by’ukuri\",\"image_path\":null},{\"id\":22,\"correct_option\":\"C\",\"question\":\"Za otobisi zagenewe gutwara abanyeshuri zishobora gushyirwaho amatara abiri asa n’icunga rihishije amyasa kugirango yerekane ko zihagaze no kwerekana ko bagomba kwitonda, ayo matara ashyirwaho ku buryo bukurikira \",\"option_a\":\"Amatara abiri ashyirwa inyuma\",\"option_b\":\"Amatara abiri ashyirwa imbere\",\"option_c\":\"Rimwe rishyirwa imbere irindi inyuma\",\"option_d\":\"b na c ni ibisubizo by’ukuri\",\"image_path\":\"\"},{\"id\":23,\"correct_option\":\"C\",\"question\":\"Iyo umuvuduko w’ibinyabiziga bidapakiye\\r\\nushobora kurenga km50 mu isaha ahategamye,\\r\\nbigomba kuba bifite ibikoresho by’ihoni\\r\\nbyumvikanira mu ntera:\",\"option_a\":\"Metero 100\",\"option_b\":\"Metero 200\",\"option_c\":\"Metero 50\",\"option_d\":\"Metero 150\",\"image_path\":null},{\"id\":24,\"correct_option\":\"C\",\"question\":\"Uri hafi kunyura k’umuyobozi\\r\\nw’ikinyamitende. Muri ibi byapa\\r\\nbikurikira nikihe wakwitondera?\\r\\n\",\"option_a\":\"images.png\",\"option_b\":\"Philippines_road_sign_R3-14.svg.png\",\"option_c\":\"Screenshot_2026-06-09_165909.png\",\"option_d\":\"Nepal_road_sign_A15.svg.png\",\"image_path\":\"\"},{\"id\":25,\"correct_option\":\"B\",\"question\":\"Nikihe cyapa cyerekena ko nta kinyabiziga\\r\\ngifite moteri cyemerewe kuhanyura?\\r\\n\",\"option_a\":\"Nepal_road_sign_A15.svg.png\",\"option_b\":\"619.jpg\",\"option_c\":\"4.jpg\",\"option_d\":\"LT_road_sign_325.png\",\"image_path\":null},{\"id\":26,\"correct_option\":\"A\",\"question\":\"Iki cyapa gisobanura iki ?\",\"option_a\":\"Iherezo ry’ibibuzwa byose mu karere ku binyabiziga bigenda\",\"option_b\":\"Ntihemerewe kuhahagarara\",\"option_c\":\"Umuvuduko ntarengwa wemewe\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":\"4.jpg\"},{\"id\":27,\"correct_option\":\"B\",\"question\":\"Ikinyabiziga gishya gikenerwa gusuzumwa bwambere nyuma y’igihe kingana iki ?\",\"option_a\":\"Nyuma y’umwaka umwe\",\"option_b\":\"Nyuma y’imyaka ibiri\",\"optio