(4, 'MUNYEMANA Amiable', '+250788815482', 16, 18, '{\"question_1\":\"B\",\"question_2\":\"A\",\"question_3\":\"A\",\"question_4\":\"C\",\"question_13\":\"D\",\"question_19\":\"D\",\"question_30\":\"B\",\"question_33\":\"A\",\"question_43\":\"D\",\"question_45\":\"A\",\"question_52\":\"C\",\"question_57\":\"A\",\"question_58\":\"D\",\"question_64\":\"D\",\"question_71\":\"D\",\"question_74\":\"A\",\"question_95\":\"B\",\"question_97\":\"A\"}', '[{\"id\":1,\"correct_option\":\"B\",\"question\":\"Mu gihe utwaye ikinyabiziga uva kuri A ugana kuri B, Iki kimenyetso kiri mu muhanda kivuze iki ?\\r\\n\",\"option_a\":\"Umuyobozi w’ikinyabiziga ashobora kunyuranaho arenze umurongo wera udacagaguye\",\"option_b\":\"Umuyobozi w’ikinyabiziga abujijwe kunyuranaho arenze imirongo yera\",\"option_c\":\"Umuyobozi w’ikinyabiziga yemerewe kunyuranaho\",\"option_d\":\"Abayobozi b’ibinyamitende gusa bemerewe kunyuranaho barenze umurongo wera udacagaguye\",\"image_path\":\"sign5.png\"},{\"id\":2,\"correct_option\":\"A\",\"question\":\"Ikinyabiziga cyose cyangwa ibinyabiziga\\r\\nbigenda bigomba kugira:\",\"option_a\":\"Umuyobozi\",\"option_b\":\"Umuherekeza\",\"option_c\":\"A na B ni ibisubizo by’ukuri\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":3,\"correct_option\":\"C\",\"question\":\"Ijambo “akayira” bivuga inzira\\r\\nnyabagendwa ifunganye yagenewe gusa:\",\"option_a\":\"Abanyamaguru\",\"option_b\":\"Ibinyabiziga bigendera ku biziga bibiri\",\"option_c\":\"A na B ni ibisubizo by’ukuri\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":4,\"correct_option\":\"C\",\"question\":\"Umurongo uciyemo uduce umenyesha\\r\\nahegereye umurongo ushobora kuzuzwa\\r\\nn’uturanga gukata tw’ibara ryera utwo\\r\\nturanga cyerekezo tumenyesha :\",\"option_a\":\"Igisate cy’umuhanda abayobozi bagomba gukurikira\",\"option_b\":\"Ahegereye umurongo ukomeje\",\"option_c\":\"Igabanurwa ry’umubare w’ibisate by’umuhanda mu cyerekezo bajyamo\",\"option